var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
var rows=new System.Collections.Generic.List<object>();System.Action<string,bool> check=(n,v)=>rows.Add(new{test=n,passed=v});
var created=new System.Collections.Generic.List<UnityEngine.Object>();
var gm=UnityEngine.Object.FindObjectOfType<GameManager>();gm.enabled=false;UnityEngine.Object.FindObjectOfType<WaveManager>().StopWaves();Time.timeScale=0;
var state=typeof(GameManager).GetProperty("CurrentState");state.SetValue(gm,GameManager.GameState.Preparation,null);
var ui=UnityEngine.Object.FindObjectOfType<UİManager>();var owner=UnityEngine.Object.FindObjectOfType<MortarTower>();
// Canlı hareket probundan kalan girişleri temizle; aşağıdaki sıra testi kendi hedeflerini ekler.
typeof(Tower).GetMethod("OnDisable",flags).Invoke(owner,null);
var originalData=owner.data;owner.data=UnityEngine.Object.Instantiate(originalData);created.Add(owner.data);owner.data.firstLevelExperience=10000;
System.Func<Vector3,bool,ElementType,Enemy> enemy=(position,air,element)=>{var go=new GameObject("MortarTestEnemy");created.Add(go);go.transform.position=position;go.tag="Enemy";var e=go.AddComponent<Enemy>();e.enabled=false;e.enemyData=ScriptableObject.CreateInstance<EnemyData>();created.Add(e.enemyData);e.enemyData.health=1000;e.enemyData.element=element;e.enemyData.experienceReward=25;e.enemyData.goldReward=0;e.enemyData.movementType=air?EnemyData.MovementType.Air:EnemyData.MovementType.Ground;e.enemyData.weaknesses=new System.Collections.Generic.List<ElementType>();e.enemyData.resistances=new System.Collections.Generic.List<ElementType>();typeof(Enemy).GetField("currenthealth",flags).SetValue(e,1000f);go.AddComponent<SphereCollider>().radius=.1f;return e;};
System.Func<Vector3,float,float,MortarProjectile> shell=(destination,damage,crit)=>{var p=UnityEngine.Object.Instantiate(owner.projectilePrefab,new Vector3(900,5,900),Quaternion.identity);created.Add(p.gameObject);p.enabled=false;p.Initialize(destination,damage,crit,owner);return p;};
System.Action<MortarProjectile> impact=p=>{Physics.SyncTransforms();typeof(MortarProjectile).GetMethod("Explode",flags).Invoke(p,null);};
try{
check("Purchased mortar initialized once with one main and four offers",owner.Backpack.Items.Count==1&&owner.myShopItems.All(i=>i!=null)&&owner.Level==1);
check("Approved base stats",owner.data.damage==70&&owner.data.attackSpeed==3&&owner.data.range==6&&owner.data.explosionRadius==1.5f);
var range=owner.GetComponentInChildren<SphereCollider>();check("World range is six and trigger enabled",range.enabled&&range.isTrigger&&Mathf.Abs(range.radius*range.transform.lossyScale.x-6)<.001f);
owner.SetTargetType(0);owner.SetTargetType(2);check("Both and air requests cannot override ground-only",owner.SelectedTargetType==Tower.TargetType.Ground);
var a=enemy(new Vector3(900,0,900),false,ElementType.Normal);var b=enemy(new Vector3(900.5f,0,900),false,ElementType.Normal);var air=enemy(new Vector3(900,0,900),true,ElementType.Normal);var far=enemy(new Vector3(905,0,900),false,ElementType.Normal);
var enter=typeof(Tower).GetMethod("OnTriggerEnter",flags);enter.Invoke(owner,new object[]{air.GetComponent<Collider>()});enter.Invoke(owner,new object[]{a.GetComponent<Collider>()});enter.Invoke(owner,new object[]{b.GetComponent<Collider>()});
var target=typeof(Tower).GetMethod("SelectTarget",flags);owner.SetTargetOrder(0);check("First entrant skips air",target.Invoke(owner,null)==a.gameObject);owner.SetTargetOrder(1);check("Last entrant selects latest ground",target.Invoke(owner,null)==b.gameObject);
var child=new GameObject("SecondCollider");child.transform.SetParent(a.transform,false);child.AddComponent<SphereCollider>().radius=.1f;
var shot=shell(a.transform.position,70,0);impact(shot);check("Area damages each ground once despite multiple colliders",a.CurrentHealth==930&&b.CurrentHealth==930);check("Air and out of radius untouched",air.CurrentHealth==1000&&far.CurrentHealth==1000);impact(shot);check("Explosion idempotent",a.CurrentHealth==930&&b.CurrentHealth==930);
var moving=enemy(new Vector3(920,0,900),false,ElementType.Normal);var fixedPoint=moving.transform.position;var movingShot=shell(fixedPoint,70,0);moving.transform.position+=Vector3.right*5;impact(movingShot);check("Moving target can escape fixed impact point",moving.CurrentHealth==1000);
var middle=shell(new Vector3(904,0,900),70,0);typeof(MortarProjectile).GetField("elapsed",flags).SetValue(middle,owner.data.mortarFlightTime*.5f);typeof(MortarProjectile).GetMethod("Update",flags).Invoke(middle,null);check("Midpoint follows parabolic arc",Vector3.Distance(middle.transform.position,new Vector3(902,2.5f+owner.data.mortarArcHeight,900))<.001f);var frozen=middle.transform.position;typeof(MortarProjectile).GetMethod("Update",flags).Invoke(middle,null);check("Pause freezes flight",middle.transform.position==frozen);
var victim=enemy(new Vector3(940,0,900),false,ElementType.Normal);var lethal=shell(victim.transform.position,2000,0);float xp=owner.Experience;impact(lethal);check("Kill credits owner XP once",owner.Experience==xp+25);impact(lethal);check("Duplicate explosion cannot repeat XP",owner.Experience==xp+25);
var critVictim=enemy(new Vector3(950,0,900),false,ElementType.Normal);impact(shell(critVictim.transform.position,70,1));check("Guaranteed critical doubles one shell",critVictim.CurrentHealth==860);
typeof(Tower).GetProperty("SelectedElement").SetValue(owner,ElementType.Water,null);
var fire=enemy(new Vector3(960,0,900),false,ElementType.Fire);var earth=enemy(new Vector3(960.5f,0,900),false,ElementType.Earth);var waterShot=shell(fire.transform.position,70,0);
typeof(Tower).GetProperty("SelectedElement").SetValue(owner,ElementType.Fire,null);impact(waterShot);check("Element captured at launch; each victim applies own multiplier",fire.CurrentHealth==895&&earth.CurrentHealth==965);
typeof(Tower).GetProperty("SelectedElement").SetValue(owner,ElementType.Normal,null);
int before=UnityEngine.Object.FindObjectsOfType<MortarProjectile>().Length;owner.Attack(air.gameObject);check("Direct Attack also rejects air",UnityEngine.Object.FindObjectsOfType<MortarProjectile>().Length==before);
for(int e=0;e<5;e++)for(int r=0;r<4;r++){var offer=ShopManager.Instance.GetRandomItem(TowerType.CannonTower,(ItemRarity)r,(ElementType)e);check("Shop pool element "+e+" rarity "+r,offer!=null&&offer.IsCompatibleWith(TowerType.CannonTower,(ElementType)e));}
check("Five recipes reference only compatible mortar items",owner.evolutionRecipes.Count==5&&owner.evolutionRecipes.All(r=>r.first.itemOwners.Contains(TowerType.CannonTower)&&r.second.itemOwners.Contains(TowerType.CannonTower)&&r.result.itemOwners.Contains(TowerType.CannonTower)));
for(int e=0;e<5;e++){var item=owner.data.GetMainItem((ElementType)e);check("Protected main variant "+e,owner.IsMainItem(item)&&item.itemShape.SequenceEqual(owner.data.defaultWeapon.itemShape));}
UİManager.activeTower=owner;BackpackUIManager.Instance.OpenBackpack(owner);UnityEngine.Object.FindObjectOfType<ShopUIManager>().UpdateShopUI();typeof(UİManager).GetMethod("RefreshTargetingControls",flags).Invoke(ui,null);check("UI locks target type but permits order",ui.targetTypeButtons.All(x=>!x.interactable)&&ui.targetOrderButtons.All(x=>x.interactable));
ui.OpenTowerTypeChange();ui.ChooseTransitionType((int)TowerType.ArrowTower);int gold=EconomyManager.Gold;var storage=owner.Storage;ui.ConfirmTransition();var archer=UİManager.activeTower;check("Mortar converts to archer retaining storage",archer is ArcherTower&&archer.Storage==storage&&EconomyManager.Gold==gold-75);
ui.OpenTowerTypeChange();ui.ChooseTransitionType((int)TowerType.CannonTower);gold=EconomyManager.Gold;ui.transitionConfirm.onClick.Invoke();var newMortar=UİManager.activeTower;check("UI can convert back to mortar retaining storage",newMortar is MortarTower&&newMortar.Storage==storage&&newMortar.SelectedTargetType==Tower.TargetType.Ground&&EconomyManager.Gold==gold-225);ui.CloseTransition();
}finally{if(owner!=null)owner.data=originalData;foreach(var obj in created)if(obj!=null)UnityEngine.Object.DestroyImmediate(obj);}
return rows;
